INSERT INTO "knowledge_documents" ("id", "title", "source_url", "content", "doc_type", "doc_category", "is_active", "ingested_at", "chunk_count", "created_at", "updated_at") VALUES ('75b97c75-0044-47db-b9fe-d98020cf6bee', 'Proven Results & Case Studies', 'https://rayvensc.com/work', 'RayvenSC has delivered results across sectors where communication failures have real consequences:

- Supported a national health authority during World Sight Day, stabilizing communication
  during a regulatory challenge.

- Developed the communications framework for a large-scale infrastructure launch across
  public and private stakeholders.

- Built a content system that improved reach and message consistency for a client.

